class Dog {
private:
    std::string name;
    std::string breed;
public:
    Dog(const std::string& name, const std::string& breed)
        : name(name), breed(breed) {}

    std::string bark() const {
        return name + ": Woof!";
    }
};

Dog dog1("Buddy", "Labrador");
