#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// C doesn't have classes, use structs and function pointers
typedef struct {
    char name[50];
    char breed[50];
    char* (*bark)(struct Dog*);
} Dog;

char* dog_bark(Dog* dog) {
    static char result[100];
    sprintf(result, "%s: Woof!", dog->name);
    return result;
}

Dog* create_dog(const char* name, const char* breed) {
    Dog* dog = malloc(sizeof(Dog));
    strcpy(dog->name, name);
    strcpy(dog->breed, breed);
    dog->bark = dog_bark;
    return dog;
}

int main() {
    Dog* dog1 = create_dog("Buddy", "Labrador");
    printf("%s\n", dog1->bark(dog1)); // Buddy: Woof!
    free(dog1);
    return 0;
}
